def centw(rgb,dep,it,pm,mask):
 ys,xs=np.where(mask); u=int(xs.mean()); v=int(ys.mean()); return proj(rgb,dep,it,pm,u,v)
def proj(rgb,dep,it,pm,u,v):
 d=dep[v,u]
 if d is None or d<=0.05 or d>2.5: return None
 return (pm@np.array([(u-it['cx'])*d/it['fx'],(v-it['cy'])*d/it['fy'],d,1.0]))[:3]
def quat(R):
 r=np.array([[R[0][0],R[0][1],R[0][2]],[R[1][0],R[1][1],R[1][2]],[R[2][0],R[2][1],R[2][2]]])
 t=float(np.trace(r))
 if t>0: w=0.25*math.sqrt(t+1); x=r[2,1]-r[1,2]; y=r[0,2]-r[2,0]; z=r[1,0]-r[0,1]
 elif r[0,0]>r[1,1] and r[0,0]>r[2,2]: x=0.25*math.sqrt(1+t-r[0,0]+r[1,1]+r[2,2]); w=(r[2,1]-r[1,2])/x; y=(r[0,2]+r[2,0])/x; z=(r[0,1]+r[1,0])/x
 elif r[1,1]>r[2,2]: y=0.25*math.sqrt(1+t-r[1,1]+r[0,0]+r[2,2]); w=(r[0,2]-r[2,0])/y; x=(r[0,1]+r[1,0])/y; z=(r[1,2]+r[2,1])/y
 else: z=0.25*math.sqrt(1+t-r[2,2]+r[0,0]+r[1,1]); w=(r[1,0]-r[0,1])/z; x=(r[0,2]+r[2,0])/z; y=(r[1,2]+r[2,1])/z
 q=np.array([w,x,y,z]); return q/np.linalg.norm(q)
